const MONTHS_ORDER = [
  'jan',
  'feb',
  'mar',
  'apr',
  'may',
  'jun',
  'jul',
  'aug',
  'sep',
  'oct',
  'nov',
  'dec',
] as const;

export const ALL_100_FEATURED_DESTINATIONS: ReadonlyArray<FeaturedDestination> =
  COMPACT_100_SEEDS.map((seed) => {
    const lowSet = new Set(seed.lowMonths);
    const buildMonthRisk = (
      m: (typeof MONTHS_ORDER)[number]
    ): MonthlyRiskRating => {
      if (lowSet.has(m)) return MonthlyRiskRating.LOW;
      if (seed.elev >= 7000) return MonthlyRiskRating.HIGH;
      return MonthlyRiskRating.MEDIUM;
    };

    return {
      destinationId: seed.id,
      regionId: seed.regionId,
      entityType: seed.entityType,
      nameEn: seed.nameEn,
      nameNe: seed.nameNe,
      indigenousOrAltNames: [seed.nameEn],
      countryCodes: seed.countryCodes,
      jurisdictionDisplay: seed.jurisdiction,
      coordinates: {
        latitude: seed.lat,
        longitude: seed.lng,
      },
      elevationMeters: seed.elev,
      primaryCategoryId: seed.cat,
      difficultySummary: `Official ${seed.cat} Expedition / Route (${seed.elev.toLocaleString('en-US')} m)`,
      permitRequirements: `Official regulatory / park permit required via ${seed.jurisdiction} authority (${seed.sourceUrl})`,
      environmentalRestrictions:
        'Strict Leave No Trace (NF-05) & mandatory camp waste pack-out compliance.',
      culturalConsiderations: seed.sacredGuardian
        ? 'Sacred mountain protocol enforced: Heritage Guardian (NF-01) cultural compliance sign-off mandatory.'
        : 'Respect local mountain community customs, refuges, and trailhead heritage sites.',
      requiresHeritageGuardianCheck: seed.sacredGuardian,
      separatedRouteIds: seed.routes,
      associatedBadgeId: `BDG-${seed.id}`,
      source_url: seed.sourceUrl,
      source_type: seed.sourceType,
      last_verified_date: '2026-11-12',
      confidence: seed.confidence,
      unverified_fields: Array.from(
        new Set([
          ...seed.unverified,
          'nearest_trauma_center_field_verification',
          'sar_dispatch_phone_and_heli_ceiling_field_verification',
        ])
      ),
      geopoliticalFlag: seed.geoFlag,
      emergencyRescueProtocol: {
        primarySarAgency: seed.sarAgency,
        emergencyPhoneNumbers: seed.sarPhones,
        nearestTraumaOrHyperbaricCenter: `${seed.jurisdiction} Regional Trauma & High-Altitude Medical Center (UNVERIFIED — Pending Phase 09 Field Check)`,
        helicopterEvacuationCeilingMeters: seed.heliCeiling,
        mandatoryInsuranceMinimumUsd: seed.elev >= 6000 ? 100000 : 50000,
        nonRescuePlatformDisclaimer: true,
      },
      seasonalRiskMatrix: {
        jan: buildMonthRisk('jan'),
        feb: buildMonthRisk('feb'),
        mar: buildMonthRisk('mar'),
        apr: buildMonthRisk('apr'),
        may: buildMonthRisk('may'),
        jun: buildMonthRisk('jun'),
        jul: buildMonthRisk('jul'),
        aug: buildMonthRisk('aug'),
        sep: buildMonthRisk('sep'),
        oct: buildMonthRisk('oct'),
        nov: buildMonthRisk('nov'),
        dec: buildMonthRisk('dec'),
        seasonalSummaryNotes: `Optimal low-risk summit/traversal windows: ${seed.lowMonths
          .map((m) => m.toUpperCase())
          .join(', ')}.`,
      },
      status: DestinationCatalogStatus.PROPOSED,
    };
  });
